          const h = this.s.slice(this.i + 2, this.i + 6)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16)); this.i += 6
        } else fail('invalid escape \\' + String.fromCodePoint(this.s.codePointAt(this.i + 1)))
      } else { out += c; this.i++ }
    }
  }
  name() {
    const c = this.s[this.i]
    if (c === '"' || c === "'") return this.quoted()
    if (!isNameCh(c)) fail('expected a name')
    const st = this.i
    while (isNameCh(this.s[this.i])) this.i++
    return this.s.slice(st, this.i)
  }
  dotted() {
    const names = []
    this.ws(); names.push(this.name()); this.ws()
    while (this.s[this.i] === '.') { this.i++; this.ws(); names.push(this.name()); this.ws() }
    return names
  }
  value(prefix) {
    const c = this.s[this.i]
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { type: 'string', value: this.quoted() }
    if (c === '[') {
      this.i++
      const items = []
      for (;;) {
        this.ws()
        if (this.s[this.i] === ']') { this.i++; break }
        if (this.i >= this.s.length || this.atEnd()) fail('unterminated array')
        items.push(this.value(prefix + '[' + items.length + ']'))
        this.ws()
        if (this.s[this.i] === ',') { this.i++; continue }
        if (this.s[this.i] === ']') { this.i++; break }
        fail('unterminated array')
      }
      return { type: 'array', items, aot: false }
