import { readFileSync } from 'node:fs'
import { parse, ConfError } from './parse.js'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'json' && mode !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
const cmp = (a, b) => {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < x.length && i < y.length; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const sorted = (m) => [...m.keys()].sort(cmp)

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1), end = '  '.repeat(ind)
  if (n.type === 'table') {
    const ks = sorted(n.map)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + toJson(n.map.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
  }
  if (n.type === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((v) => pad + toJson(v, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.value)
}
function keys(n, path, out) {
  if (n.type === 'table') {
    for (const k of sorted(n.map)) {
      const p = path ? path + '.' + k : k, c = n.map.get(k)
      out.push(p + ' ' + c.type); keys(c, p, out)
    }
  } else if (n.type === 'array') {
    n.items.forEach((c, i) => { const p = path + '[' + i + ']'; out.push(p + ' ' + c.type); keys(c, p, out) })
  }
}

let root
try {
  root = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof ConfError)) throw e
  process.stderr.write('error: ' + e.message + '\n')
  process.exit(2)
}
if (mode === 'json') process.stdout.write(toJson(root, 0) + '\n')
else { const out = []; keys(root, '', out); process.stdout.write(out.map((l) => l + '\n').join('')) }
